import pdfplumber

targets = ['自然语言处理', '软件体系结构', '思政B']
found = {}

with pdfplumber.open('/app/25-26学年第一学期课程表.pdf') as pdf:
    for i, page in enumerate(pdf.pages):
        text = page.extract_text()
        if not text:
            continue
        for t in targets:
            if t in text:
                key = t
                if key not in found:
                    found[key] = []
                found[key].append(i+1)

for k, v in found.items():
    print(f'{k}: pages {v}')
